class NumberConverter:

    @staticmethod
    def decimal_to_binary(decimal_num):
        """Convert a number from decimal format to binary format.
        :param decimal_num: int, decimal number
        :return: str, the binary representation of an integer.
        """
        if not isinstance(decimal_num, int):
            raise TypeError('Input must be an integer.')
        if decimal_num < 0:
            raise ValueError('Negative numbers cannot be converted to binary using this method.')
        if decimal_num == 0:
            return '0'
        binary_num = ''
        while decimal_num > 0:
            binary_num = str(decimal_num % 2) + binary_num
            decimal_num //= 2
        return binary_num

    @staticmethod
    def binary_to_decimal(binary_num):
        """Convert a number from binary format to decimal format.
        :param binary_num: str, binary number
        :return: int, the decimal representation of binary number str.
        """
        if not binary_num:
            return 0
        if not all((char in '01' for char in binary_num)):
            raise ValueError('Invalid binary number')
        return int(binary_num, 2)

    @staticmethod
    def decimal_to_octal(decimal_num):
        """Convert a number from decimal format to octal format.
        :param decimal_num: int, decimal number
        :return: str, the octal representation of an integer.
        """
        if not isinstance(decimal_num, int):
            raise TypeError('Input must be an integer.')
        if decimal_num < 0:
            raise ValueError('Input must be a non-negative integer.')
        return oct(decimal_num)[2:]

    @staticmethod
    def octal_to_decimal(octal_num):
        """Convert a number from octal format to decimal format.
        :param octal_num: str, octal num
        :return: int, the decimal representation of octal number str.
        """
        if not octal_num:
            return 0
        if not all((char in '01234567' for char in octal_num)):
            raise ValueError('Invalid octal number')
        return int(octal_num, 8)

    @staticmethod
    def decimal_to_hex(decimal_num):
        """Convert a number from decimal format to hex format.
        :param decimal_num: int, decimal number
        :return: str, the hex representation of an integer.
        """
        if not isinstance(decimal_num, int):
            raise TypeError('Input must be an integer.')
        if decimal_num < 0:
            raise ValueError('Input must be a non-negative integer.')
        return hex(decimal_num)[2:].upper()

    @staticmethod
    def hex_to_decimal(hex_num):
        """Convert a number from hexadecimal format to decimal format.
        :param hex_num: str, a string representing a hexadecimal number.
        :return: int, the decimal representation of the hexadecimal number.
        """
        if not hex_num:
            raise ValueError('Input string is empty')
        try:
            return int(hex_num, 16)
        except ValueError:
            raise ValueError('Input string contains invalid characters')

